513|/// Walk only existing projected nodes relative to the pinned root descriptor.
514|/// Do not follow symlinks or create files on a missing/unmounted namespace.
515|fn open_relative(root: &File, relative: &str, write: bool) -> Result<File> {
516|    let components: Vec<_> = Path::new(relative).components().collect();
517|    ensure!(!components.is_empty(), "empty projected path");
518|    let mut parent = root.try_clone()?;
519|    let mount_id = fd_mount_id(root)?;
520|    for (index, component) in components.iter().enumerate() {
521|        let Component::Normal(name) = component else {
522|            bail!("unsafe projected path");
523|        };
524|        use std::os::unix::ffi::OsStrExt;
525|        let name = CString::new(name.as_bytes())?;
526|        let last = index + 1 == components.len();
527|        let flags = libc::O_CLOEXEC
528|            | libc::O_NOFOLLOW
529|            | if last {
530|                if write { libc::O_RDWR } else { libc::O_RDONLY }
531|            } else {
532|                libc::O_RDONLY | libc::O_DIRECTORY
533|            };
534|        // SAFETY: parent is a live directory descriptor; name is NUL terminated.
535|        let fd = unsafe { libc::openat(parent.as_raw_fd(), name.as_ptr(), flags) };
536|        if fd < 0 {
537|            return Err(std::io::Error::last_os_error())
538|                .with_context(|| format!("open mounted {relative}"));
539|        }
540|        // SAFETY: openat returned a newly owned descriptor.
541|        parent = unsafe { File::from_raw_fd(fd) };
542|        ensure!(
543|            fd_mount_id(&parent)? == mount_id,
544|            "projected path crosses the pinned mount boundary"
545|        );
546|    }
547|    Ok(parent)
548|}
