{"content":"1|//! Typed model of Incus instance **devices**, faithful to the official Incus
2|//! API (`shared/api`: `map[string]map[string]string`).
3|//!
4|//! Incus stores every device value as a string (`"nat": "true"`, `"uid": "0"`).
5|//! To present a typed, schema-renderable model while round-tripping losslessly
6|//! with the REST API, numeric/boolean keys use the [`StrBool`]/[`StrInt`]
7|//! coercion newtypes: they deserialize from either a JSON string or a native
8|//! value and **always serialize back to a string**, so a `Device` round-trips
9|//! to the all-string map Incus expects.
10|//!
11|//! [`Device`] is an internally-tagged enum (`#[serde(tag = "type")]`) with one
12|//! variant per device type. Through [`super::schemars_adapter`] it renders into
13|//! the plugin schema as a `FieldType::OneOf` discriminated union (the `oneOf`
14|//! emitted by schemars for the tagged enum). The device *name* (the Incus map
15|//! key) is carried alongside in [`NamedDevice`] so the `devices` field renders
16|//! as `Array<OneOf<…>>` rather than an opaque map.
17|
18|use serde::{Deserialize, Deserializer, Serialize, Serializer};
19|use simd_json::prelude::*;
20|use std::collections::BTreeMap;
21|
22|/// A boolean Incus value stored on the wire as the string `"true"`/`"false"`.
23|#[derive(Debug, Clone, Copy, PartialEq, Eq)]
24|pub struct StrBool(pub bool);
25|
26|impl Serialize for StrBool {
27|    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
28|        s.serialize_str(if self.0 { "true" } else { "false" })
29|    }
30|}
31|
32|impl<'de> Deserialize<'de> for StrBool {
33|    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
34|        struct V;
35|        impl serde::de::Visitor<'_> for V {
36|            type Value = StrBool;
37|            fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
38|                f.write_str("a boolean or a boolean-like string")
39|            }
40|            fn visit_bool<E: serde::de::Error>(self, v: bool) -> Result<StrBool, E> {
41|                Ok(StrBool(v))
42|            }
43|            fn visit_str<E: serde::de::Error>(self, v: &str) -> Result<StrBool, E> {
44|                match v.trim().to_ascii_lowercase().as_str() {
45|                    "true" | "1" | "yes" | "on" => Ok(StrBool(true)),
46|                    "false" | "0" | "no" | "off" | "" => Ok(StrBool(false)),
47|                    other => Err(E::custom(format!("invalid boolean string: {other}"))),
48|                }
49|            }
50|        }
51|        d.deserialize_any(V)
52|    }
53|}
54|
55|/// An integer Incus value stored on the wire as a decimal string (e.g. `"0"`).
56|#[derive(Debug, Clone, Copy, PartialEq, Eq)]
57|pub struct StrInt(pub i64);
58|
59|impl Serialize for StrInt {
60|    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
61|        s.serialize_str(&self.0.to_string())
62|    }
63|}
64|
65|impl<'de> Deserialize<'de> for StrInt {
66|    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
67|        struct V;
68|        impl serde::de::Visitor<'_> for V {
69|            type Value = StrInt;
70|            fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
71|                f.write_str("an integer or an integer-like string")
72|            }
73|            fn visit_i64<E: serde::de::Error>(self, v: i64) -> Result<StrInt, E> {
74|                Ok(StrInt(v))
75|            }
76|            fn visit_u64<E: serde::de::Error>(self, v: u64) -> Result<StrInt, E> {
77|                Ok(StrInt(v as i64))
78|            }
79|            fn visit_str<E: serde::de::Error>(self, v: &str) -> Result<StrInt, E> {
80|                v.trim()
81|                    .parse::<i64>()
82|                    .map(StrInt)
83|                    .map_err(|_| E::custom(format!("invalid integer string: {v}")))
84|            }
85|        }
86|        d.deserialize_any(V)
87|    }
88|}
