90|/// A device paired with its Incus device name (the map key).
91|///
92|/// Renders as an object `{ name, device: oneOf<…> }`; the `device` union is the
93|/// schema-visible discriminated type. The REST layer flattens a `Vec` of these
94|/// into Incus's `map[name] -> { type, … }` and back.
95|#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, schemars::JsonSchema)]
96|pub struct NamedDevice {
97|    /// Incus device name (the map key, e.g. `"eth0"`, `"grpc-socket"`).
98|    pub name: String,
99|    /// The typed device definition.
100|    pub device: Device,
101|}
102|
103|/// A single Incus device, tagged by its `type` key.
104|///
105|/// One variant per official Incus device type. `nic`, `gpu` and `infiniband`
106|/// carry their sub-type selector (`nictype`/`gputype`) as a field rather than a
107|/// nested union, matching the flat `map[string]string` the API uses.
108|#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, schemars::JsonSchema)]
109|#[serde(tag = "type", rename_all = "kebab-case")]
110|pub enum Device {
111|    /// Network interface. `nictype` (or a managed `network`) selects the kind.
112|    Nic(NicDevice),
113|    /// Disk / filesystem / block volume mount.
114|    Disk(DiskDevice),
115|    /// Unix character device passthrough (containers only).
116|    UnixChar(UnixDevice),
117|    /// Unix block device passthrough (containers only).
118|    UnixBlock(UnixDevice),
119|    /// USB device passthrough.
120|    Usb(UsbDevice),
121|    /// GPU passthrough. `gputype` selects physical/mdev/mig/sriov.
122|    Gpu(GpuDevice),
123|    /// InfiniBand device. `nictype` selects physical/sriov.
124|    Infiniband(InfinibandDevice),
125|    /// Proxy device (port/socket forwarding between host and instance).
126|    Proxy(ProxyDevice),
127|    /// Hot-pluggable Unix device matched by vendor/product id.
128|    UnixHotplug(UnixHotplugDevice),
129|    /// Trusted Platform Module.
130|    Tpm(TpmDevice),","total_lines":762,"file_size":29551,"truncated":true,"hint":"Use offset=131 to continue reading (showing 1-130 of 762 lines)","is_binary":false,"is_image":false,"not_found":false}

